description:
Model events and `WaitForMultipleObjects` (lesson 4.02):

```cpp
class Event
{
public:
    explicit Event(bool manualReset, bool initiallySet = false);
    void set();
    void reset();
    bool isSet() const;
    bool tryWait();
};

struct Waitable { Event* event; bool processEnded; };
std::optional<std::size_t> waitAny(std::vector<Waitable>& objects);
```

- **tryWait** is a wait with a zero timeout: if the event is set it succeeds, and an **auto-reset** event resets itself; a manual-reset event stays set. If not set, it returns false.
- **set** and **reset** change the state; setting an event that is already set does nothing more (events do not count).
- **waitAny** is `WaitForMultipleObjects` with "any" and a zero timeout: each entry is either an event (`event` not null) or a process handle (`event` null; signalled when `processEnded`). It returns the **lowest** index that is signalled, consuming an auto-reset event at that index only, or `std::nullopt` if none is.

starter.solution.cpp:
#include <optional>
#include <vector>

class Event
{
public:
    explicit Event(bool manualReset, bool initiallySet = false) {}
    void set() {}
    void reset() {}
    bool isSet() const { return false; }
    bool tryWait() { return false; }
};

struct Waitable { Event* event; bool processEnded; };
std::optional<std::size_t> waitAny(std::vector<Waitable>& objects) { return std::nullopt; }

solution.solution.cpp:
#include <optional>
#include <vector>

class Event
{
public:
    explicit Event(bool manualReset, bool initiallySet = false) : manual{ manualReset }, state{ initiallySet } {}
    void set() { state = true; }
    void reset() { state = false; }
    bool isSet() const { return state; }

    bool tryWait()
    {
        if (!state) return false;
        if (!manual) state = false;
        return true;
    }

private:
    bool manual;
    bool state;
};

struct Waitable { Event* event; bool processEnded; };

std::optional<std::size_t> waitAny(std::vector<Waitable>& objects)
{
    for (std::size_t i{ 0 }; i < objects.size(); ++i)
    {
        if (objects[i].event) { if (objects[i].event->tryWait()) return i; }
        else if (objects[i].processEnded) return i;
    }
    return std::nullopt;
}

unitTests:
TEST("auto-reset lets one waiter through") {
    Event e{ false };
    CHECK(!e.tryWait());
    e.set();
    e.set();
    CHECK(e.tryWait());
    CHECK(!e.tryWait());
    CHECK(!e.isSet());
}
TEST("manual-reset stays set") {
    Event e{ true };
    e.set();
    CHECK(e.tryWait());
    CHECK(e.tryWait());
    CHECK(e.isSet());
    e.reset();
    CHECK(!e.tryWait());
    Event started{ true, true };
    CHECK(started.tryWait());
}
TEST("waiting for any, lowest index first") {
    Event stop{ true }, data{ false };
    std::vector<Waitable> w{ { &stop, false }, { nullptr, false }, { &data, false } };
    CHECK(!waitAny(w).has_value());
    data.set();
    CHECK_EQ(waitAny(w).value_or(99), 2u);
    CHECK(!data.isSet());
    data.set();
    stop.set();
    CHECK_EQ(waitAny(w).value_or(99), 0u);
    CHECK(data.isSet());
}
TEST("a process handle in the list") {
    Event data{ false };
    std::vector<Waitable> w{ { nullptr, false }, { &data, false } };
    w[0].processEnded = true;
    data.set();
    CHECK_EQ(waitAny(w).value_or(99), 0u);
    CHECK(data.isSet());
    CHECK_EQ(waitAny(w).value_or(99), 0u);
}

